#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""From the critique workflow's return (saved verbatim as critique/RESULT.json by the lead) write one jsonl per lens
(critique/<lens>.jsonl: the findings with the skeptic's vote) and critique/SUMMARY.json ({"html": ...}, Arabic) for the
owner page. The rulings are in LEAD-DECISIONS.md and are not derived from the votes: the votes are the record."""
import json, os
H = '/home/user/ElmsNest/brief/side-pages/pdp2/critique'
R = json.load(open(f'{H}/RESULT.json', encoding='utf-8'))
by = {}
for f in R['findings']: by.setdefault(f['lens'], []).append(f)
for lens, fs in by.items():
    with open(f'{H}/{lens}.jsonl', 'w', encoding='utf-8') as out:
        for f in fs: out.write(json.dumps(f, ensure_ascii=False) + '\n')
n = len(R['findings'])
confirmed = sum(1 for f in R['findings'] if f.get('vote') and not f['vote']['refuted'])
refuted = sum(1 for f in R['findings'] if f.get('vote') and f['vote']['refuted'])
AR = {'shopper': 'المشتري', 'owner': 'أنت', 'honesty': 'حارس الصدق', 'designer': 'المصمّم', 'engineer': 'المهندس'}
scores = ' · '.join(f"{AR.get(l['lens'], l['lens'])} {l['score']}" for l in R['lenses'])
html = f'''
<p>خمس عدسات قرأت اللقطات الحقيقية للصفحات الخمس على ثيم التطوير (360 و390 و1366) والملفات نفسها: مشترٍ لأول مرة على هاتف، أنت بحكمك، حارس الصدق، مصمّم، مهندس — الدرجات من 10: {scores}. أعطت {n} ملاحظة، وعلى كل ملاحظة مشكّك حاول نقضها بالدليل (يفتح اللقطة أو الملف ويقيس) وبالنطاق (هل هي داخل عقد الجولة). النتيجة: {confirmed} مؤكَّدة و{refuted} منقوضة. الأحكام كُتبت قبل الإصلاح (<span dir="ltr">critique/LEAD-DECISIONS.md</span>).</p>
<h4 style="margin:18px 0 6px">ما تغيّر بعد النقد</h4>
<ul class="list">
<li><b>الخطأ الحقيقي كان لي:</b> صورة حبل الإضاءة على الهاتف حملت شارة مطبوعة «עמידות IP65 / מתאימות לשימוש חוץ» — قصصتُ الملف عند 210 بكسل معتمداً على صورة مصغّرة، والشارة تمتدّ حتى 355. العدسات الخمس كلها رأتها، والمشكّكون أكّدوها بثقة 0.95. أُعيد القصّ من 380 (1254×874)، ورُفعت الصورة من جديد، وقِيست الصفحة ثانيةً.</li>
<li><b>بقايا في صورتين أخريين:</b> ساقا شخص في زاوية صورة الأعمدة القوية (قُصّ 90 بكسل من الأعلى)، وخطّ من عنوان مطبوع على حافة صورة الدرج (قُصّ 15 بكسل). وثلاث صور كانت أثقل من 220 كيلوبايت أُعيد ضغطها (1100 بكسل).</li>
<li><b>القصّ:</b> سبوت الحديقة (lantern 9) كان رأسه ولوحه ملتصقين بالحافة على الهاتف — صار القصّ من اليسار؛ أول مصباح إديسون كان مقطوع الرأس على الحاسوب — رُفع القصّ.</li>
<li><b>النصّ:</b> «בלילה» تكرّرت أربع مرات في 290 بكسل على صفحة الكشّاف، فسقطت من سطر الحديقة: «אור מכוון אל מה שרוצים לראות.». فانوس التخييم كان يُعنون «בלילה, בגינה» ووصفه لا يذكر حديقة أصلاً، فصار «בלילה, בשטח» (كلمة الوصف نفسها).</li>
<li><b>صفّ «כשמחשיך»:</b> جملتاه كانتا فقرة واحدة تنكسر في منتصف الجملة (كلمة يتيمة على الحاسوب) — صارت كل جملة سطراً؛ الصفّ كان ملتصقاً بنصّ الصورة (28 بكسل) ومعلّقاً فوق الأرقام بلا خطّ يغلقه — أُغلق بخطّ رفيع وأُبعد 16 بكسل؛ وعلى الحاسوب كان خطّه يمتدّ بعرض الصفحة بينما صفوف الأرقام تحته نصف عرض — صار على عمود الأرقام نفسه.</li>
<li><b>الحالة بلا صورة</b> (12 منتجاً): كانت عنواناً بحجم التعليق فوق سطر ورابط، تُقرأ كصورة لم تُحمَّل — صارت صفّاً على خطّ رفيع بحجم صفّ «כשמחשיך»، فيقرأ الصفّان قبل الأرقام كقائمة مصمَّمة.</li>
<li><b>حارسان في الكود:</b> خيار «صورة الكولكشن» لا يعرض صورة إن لم يُعثر على المنتج المصوَّر (كي لا تظهر صورة منتج آخر بلا سطر كرديت)؛ والملفات الأضيق من 1254 تعرض عرضها الحقيقي للمتصفح.</li>
</ul>
<h4 style="margin:18px 0 6px">مراجعة ثانية بعد الإصلاح</h4>
<p>عدستان (العقد والصورة) راجعتا الجولة الثانية بعد نشرها على ثيم التطوير، ومشكّك على كل ملاحظة: الإصلاحات الثلاثة عشر كلها في الملفات وعلى اللقطات. عشر ملاحظات صغيرة، ثماني مؤكَّدة، نُفّذت في جولة ثالثة: قصّ إديسون على الحاسوب (كان لا يزال يقطع رأس المصباح الأول)، قصّ حبل الإضاءة على الهاتف (كان الجذع الملفوف يخرج من الإطار)، إغلاق صفّ النصّ بخطّ رفيع ومشاركته الخطّ مع صفّ «כשמחשיך»، عمود تسميات أعرض للصفّين على الحاسوب (عنوان «בלילה, על השביל» كان ينكسر)، وحارسان صغيران في الكود. المنقوضتان: عمود الستانلس الثالث سليم (قِيس)، وشريط داكن في لقطات 360 هو من أداة التصوير لا من الصفحة.</p>
<h4 style="margin:18px 0 6px">ما لم أغيّره، وهو لك</h4>
<ul class="list">
<li><b>اثنا عشر منتجاً بلا صورة.</b> عدسة «المالك» في النقد قالت إن العلاج الوحيد صورة ليلية نظيفة لكل منتج منها — بلوك في محرّر الثيم، لا كود. القائمة في جدول المصادر أعلاه.</li>
<li><b>الجملة الثانية في «כשמחשיך»</b> («יותר שמש ביום, יותר אור בלילה.») قال عنها المشتري والمالك إنها سطر «לא מתאים» بصيغة موجبة. أبقيتُها لأن الأول ينبّه والثاني يفسّر، وهي حقل يمكن إفراغه.</li>
<li><b>سطر العائلة تحت الصورة</b> يشبه، بكلمات أخرى، سطر «מתאים כדי…» في أعلى الصفحة (الجدار: «نقطة» مرتين). أبقيتُه: الأول يقول لماذا المصباح، والثاني كيف يبدو ضوءه. حقول.</li>
<li><b>مصباحا الجدار الداخليان</b> (indoor-outdoor و6W) صورتهما لقطة استوديو على جدار رمادي تحت عنوان «בלילה, על הקיר» — هما منتجك على جدار، لا ليل ولا مكان؛ الأفضل إطار ليلي حين يتوفّر.</li>
<li><b>على الحاسوب</b> صورة القسم هي نفسها إحدى الصور المصغّرة في المعرض الظاهر فوقها — ثمن «صورك أنت فقط»؛ على الهاتف لا يراها من لا يسحب.</li>
<li><b>إضاءة الدرج والدك</b> تُعنون «בלילה, על השביל» لأن كولكشنها كولكشن الممرّ؛ كلمة «מדרגות» ليست في المفردات المرخّصة، فهي لك: عنوان خاص لهذين المنتجين إن أردت.</li>
</ul>
'''
json.dump({'html': html, 'n': n, 'confirmed': confirmed, 'refuted': refuted}, open(f'{H}/SUMMARY.json', 'w', encoding='utf-8'), ensure_ascii=False)
print(f'{n} findings: {confirmed} confirmed, {refuted} refuted → SUMMARY.json + {len(by)} jsonl files')
